fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn seq(seed: i32, i: i32) -> i32 {
    hash(seed * 97 + i) % 4
}

fn pad_color(q: i32, lit: i32) -> i32 {
    match q {
        0 => { if lit == 1 { 0xff6666 } else { 0x701818 } }
        1 => { if lit == 1 { 0x66ff66 } else { 0x187018 } }
        2 => { if lit == 1 { 0x6688ff } else { 0x182070 } }
        _ => { if lit == 1 { 0xffee66 } else { 0x706818 } }
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 1);
        host::display::state_set(2, 0);
        host::display::state_set(3, 0);
        host::display::state_set(4, 0);
        host::display::state_set(5, 0);
        host::display::state_set(7, 1);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(6) == 0;
    host::display::state_set(6, down);
    let level: i32 = host::display::state_get(1);
    let phase: i32 = host::display::state_get(2);
    let sd: i32 = host::display::state_get(7);
    let tones = [262, 330, 392, 523];
    let mut lit: i32 = -1;
    if phase == 0 {
        let idx: i32 = host::display::state_get(3);
        let timer: i32 = host::display::state_get(4);
        if timer == 0 {
            host::audio::tone(tones[seq(sd, idx)], 200, 0);
        }
        if timer < 24 { lit = seq(sd, idx); }
        if timer >= 36 {
            host::display::state_set(4, 0);
            if idx + 1 >= level {
                host::display::state_set(2, 1);
                host::display::state_set(5, 0);
            } else {
                host::display::state_set(3, idx + 1);
            }
        } else {
            host::display::state_set(4, timer + 1);
        }
    } else if phase == 1 {
        if tap {
            let mut q: i32 = 0;
            if host::display::pointer_x() >= w / 2 { q = 1; }
            if host::display::pointer_y() >= h / 2 { q = q + 2; }
            let ii: i32 = host::display::state_get(5);
            if q == seq(sd, ii) {
                host::audio::tone(tones[q], 150, 0);
                if ii + 1 >= level {
                    host::display::state_set(1, level + 1);
                    host::display::state_set(2, 0);
                    host::display::state_set(3, 0);
                    host::display::state_set(4, 0);
                } else {
                    host::display::state_set(5, ii + 1);
                }
            } else {
                host::audio::tone(110, 500, 1);
                host::display::state_set(2, 2);
            }
        }
    } else {
        if tap {
            host::display::state_set(7, sd + 1);
            host::display::state_set(1, 1);
            host::display::state_set(2, 0);
            host::display::state_set(3, 0);
            host::display::state_set(4, 0);
        }
    }
    host::display::clear(0x000000);
    if phase == 2 {
        host::display::draw_string(130, 190, "GAME OVER", 0xff4040, 4);
        host::display::draw_string(130, 260, "YOU REACHED LEVEL", 0x808080, 2);
        host::display::draw_number(410, 254, level, 0xffffff, 3);
        host::display::draw_string(140, 320, "TAP TO RESTART", 0x808080, 2);
    } else {
        let mut q: i32 = 0;
        while q < 4 {
            let mut on: i32 = 0;
            if q == lit { on = 1; }
            let qx: i32 = (q % 2) * (w / 2);
            let qy: i32 = (q / 2) * (h / 2);
            host::display::fill_rect(qx + 8, qy + 8, w / 2 - 16, h / 2 - 16, pad_color(q, on));
            q = q + 1;
        }
        host::display::draw_number(w / 2 - 10, h / 2 - 12, level, 0xffffff, 3);
        if phase == 1 {
            host::display::draw_string(w / 2 - 40, h / 2 + 20, "YOUR TURN", 0xffffff, 1);
        }
    }
    host::display::present();
}
